class UserManager {
  constructor() {
    this.users = new Map();
    this.nextId = 1;
  }

  // Helper method to validate email format
  static validateEmail(email) {
    const emailRegex = /^[^\s@]+@[^\s@]+\.[^\s@]+$/;
    return emailRegex.test(email);
  }

  // Helper method to validate age
  static validateAge(age) {
    return typeof age === 'number' && age > 0;
  }

  // Add a user to the collection
  addUser(user) {
    if (!user.name || !UserManager.validateEmail(user.email) || !UserManager.validateAge(user.age)) {
      throw new Error('Invalid user data. Ensure a valid name, email, and a positive age.');
    }

    const id = this.nextId++;
    const newUser = { id, ...user };
    this.users.set(id, newUser);
    return id;
  }

  // Retrieve a user by their ID
  getUserById(id) {
    if (typeof id !== 'number' || id <= 0) {
      throw new Error('Invalid ID. ID must be a positive number.');
    }

    const user = this.users.get(id);
    if (!user) {
      throw new Error(`User with ID ${id} not found.`);
    }

    return user;
  }

  // Update user details by ID
  updateUser(id, updates) {
    if (!this.users.has(id)) {
      throw new Error(`Cannot update user. User with ID ${id} not found.`);
    }

    const currentUser = this.users.get(id);

    if (updates.email && !UserManager.validateEmail(updates.email)) {
      throw new Error('Invalid email format.');
    }

    if (updates.age !== undefined && !UserManager.validateAge(updates.age)) {
      throw new Error('Invalid age. Age must be a positive number.');
    }

    const updatedUser = { ...currentUser, ...updates };
    this.users.set(id, updatedUser);
    return updatedUser;
  }

  // Delete a user by ID
  deleteUser(id) {
    if (!this.users.has(id)) {
      throw new Error(`Cannot delete user. User with ID ${id} not found.`);
    }
    this.users.delete(id);
    return true;
  }

  // Retrieve all users
  getAllUsers() {
    return Array.from(this.users.values());
  }
}

